content.text:
The investigation points to one fault: a network delay on the search→geo connection. I didn't run the ~50 calls; I stopped once the evidence was conclusive.

```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "network_delay",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH c AS (SELECT trace_id, span_id, service_name csvc, span_name cname, time ct FROM abnormal_traces WHERE attr_span_kind='Client'), s AS (SELECT trace_id, parent_span_id, service_name ssvc, time st FROM abnormal_traces WHERE attr_span_kind='Server') SELECT csvc, ssvc, cname, count(*) n, round(approx_quantile(extract(epoch FROM (st-ct)),0.5),4) gap_p50_s, round(approx_quantile(extract(epoch FROM (st-ct)),0.95),4) gap_p95_s FROM c JOIN s ON s.parent_span_id=c.span_id GROUP BY 1,2,3 ORDER BY gap_p50_s DESC",
          "claim": "search→geo Nearby calls take a median 1.43 s before geo's server span starts; all other caller→callee pairs stay around 0.3 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration,0.5)/1e6 p50_ms, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='geo' AND span_name='geo.Geo/Nearby' GROUP BY 1,2",
          "claim": "geo's own server-side Nearby spans stay fast, p50 about 0.14 ms, the same as in the normal period."
        },
        {
          "kind": "metric",
          "sql": "SELECT service_name, metric, round(avg(value),1) avg_v, round(max(value),1) max_v, count(*) n FROM abnormal_metrics_sum WHERE metric IN ('k8s.pod.network.errors','k8s.pod.network.io') AND service_name IN ('search','geo') GROUP BY 1,2",
          "claim": "Search and geo pod network I/O and error counters show no change; the delay is not packet loss or throughput saturation."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms, avg(duration)/1e6 avg_ms FROM abnormal_traces WHERE service_name IN ('frontend','search') AND span_name IN ('HTTP /hotels','search.Search/Nearby') GROUP BY 1,2",
          "claim": "Frontend's /hotels p95 rises to about 2.7 s, matching search.Search/Nearby at about 2.7 s, versus about 18 ms normally."
        }
      ]
    }
  ]
}
```

